void rdpsnd_virtual_channel_event_terminated(RDICchannelEvent *ev) { if (ev) { if (ev->channel_event_queue) MessageQueue_PostQuit(ev->channel_event_queue, 0L); if (ev->next) { WaitForSingleObject(ev->next, -1L); CloseHandle(ev->next); } MessageQueue_Free(ev->channel_event_queue); free_internals(ev); audio_formats_free(ev->channel_buffer, 1); free(ev->channel_buffer_end); free(ev->channel_buffer); ev->channel_buffer_size = 0; } free(ev); }